async function createJob(){let n=document.getElementById("jn").value.trim();if(!n)return toast("Enter a job name.",true);let r=await db.from("jobs").insert({owner_id:S.user.id,name:n,description:document.getElementById("jd").value.trim()||null,visibility:document.getElementById("jv").value,location_text:document.getElementById("jl").value.trim()||null,join_code:codegen()}).select().single();if(r.error)return toast(r.error.message,true);S.jobs.unshift(r.data);S.job=r.data;render()}
function codegen(){let a="ABCDEFGHJKLMNPQRSTUVWXYZ23456789",s="";for(let i=0;i<6;i++)s+=a[Math.floor(Math.random()*a.length)];return s.slice(0,3)+"-"+s.slice(3)}
async function regen(){let r=await db.from("jobs").update({join_code:codegen()}).eq("id",S.job.id).select().single();if(r.error)return toast(r.error.message,true);S.job=r.data;S.jobs=S.jobs.map(j=>j.id===r.data.id?r.data:j);render();toast("New join code created.")}
async function removeWorker(id){if(!confirm("Remove this worker? Their history stays."))return;let r=await db.from("job_workers").update({status:"inactive",left_at:new Date().toISOString()}).eq("id",id);if(r.error)return toast(r.error.message,true);render()}
async function restore(id){let r=await db.from("job_workers").update({status:"active",left_at:null}).eq("id",id);if(r.error)return toast(r.error.message,true);render()}
async function reviewJoin(id,status,wid){let r=await db.from("job_join_requests").update({status,reviewed_by:S.user.id,reviewed_at:new Date().toISOString()}).eq("id",id).select().single();if(r.error)return toast(r.error.message,true);if(status==="approved"){let x=await db.from("job_workers").upsert({job_id:S.job.id,worker_id:wid,status:"active"},{onConflict:"job_id,worker_id"});if(x.error)return toast(x.error.message,true)}render();toast(status==="approved"?"Worker approved.":"Denied.")}
async function reviewTime(id,status){let r=await db.from("time_change_requests").update({status,reviewed_by:S.user.id,reviewed_at:new Date().toISOString()}).eq("id",id).select().single();if(r.error)return toast(r.error.message,true);if(status==="approved"){let x=r.data;if(x.time_record_id){let field=x.request_type==="clock_in"?"clock_in":"clock_out";let u=await db.from("time_records").update({[field]:x.requested_time,manager_edited:true,edited_by:S.user.id,edited_at:new Date().toISOString()}).eq("id",x.time_record_id);if(u.error)return toast(u.error.message,true)}else{let u=await db.from("time_records").insert({job_id:x.job_id,worker_id:x.worker_id,clock_in:x.requested_time,notes:x.reason||null,manager_edited:true,edited_by:S.user.id,edited_at:new Date().toISOString()});if(u.error)return toast(u.error.message,true)}}render();toast(status==="approved"?"Approved.":"Denied.")}
async function clockIn(){let r=await db.from("time_records").insert({job_id:S.job.id,worker_id:S.user.id,clock_in:new Date().toISOString()});if(r.error)return toast(r.error.message,true);render();toast("Clocked in.")}
async function clockOut(id){let r=await db.from("time_records").update({clock_out:new Date().toISOString()}).eq("id",id).eq("worker_id",S.user.id).select();if(r.error)return toast(r.error.message,true);if(!r.data||!r.data.length)return toast("Couldn't clock out: the database blocked it. Run clockout-fix.sql in Supabase, then try again.",true);render();toast("Clocked out.")}
function custom(type,record){let now=new Date(),h=now.getHours()%12||12,m=String(now.getMinutes()).padStart(2,"0"),ap=now.getHours()>=12?"PM":"AM",d=document.createElement("dialog");d.innerHTML=`<h2>Request Custom ${type==="clock_in"?"Clock In":"Clock Out"}</h2><p>Your employer must approve this request.</p><div class="picker"><select id="h">${Array.from({length:12},(_,i)=>`<option ${i+1==h?"selected":""}>${i+1}</option>`).join("")}</select><select id="m">${Array.from({length:60},(_,i)=>`<option ${String(i).padStart(2,"0")==m?"selected":""}>${String(i).padStart(2,"0")}</option>`).join("")}</select><select id="a"><option ${ap==="AM"?"selected":""}>AM</option><option ${ap==="PM"?"selected":""}>PM</option></select></div><label>Optional description</label><textarea id="reason" placeholder="Why do you need this time?"></textarea><div class="actions"><button class="primary" id="send">Submit Request</button><button class="secondary" onclick="this.closest('dialog').close()">Cancel</button></div>`;document.body.append(d);d.showModal();d.querySelector("#send").onclick=async()=>{let hh=+d.querySelector("#h").value%12;if(d.querySelector("#a").value==="PM")hh+=12;let dt=new Date();dt.setHours(hh,+d.querySelector("#m").value,0,0);let r=await db.from("time_change_requests").insert({job_id:S.job.id,worker_id:S.user.id,time_record_id:record||null,request_type:type,requested_time:dt.toISOString(),reason:d.querySelector("#reason").value.trim()||null});d.close();d.remove();if(r.error)return toast(r.error.message,true);toast("Request sent to your employer.")}
}
async function browse(){let r=await db.from("jobs").select("*").eq("visibility","public").eq("active",true).order("created_at",{ascending:false});if(r.error)return toast(r.error.message,true);let d=document.createElement("dialog");d.innerHTML=`<h2>🌎 Browse Jobs</h2>${(r.data||[]).map(j=>`<div class="item"><h3>${esc(j.name)}</h3><p>${esc(j.description||"No description")}<br>${esc(j.location_text||"")}</p><button class="primary" onclick="requestJoin('${j.id}',this)">Request to Join</button></div>`).join("")||`<div class="empty">No public jobs.</div>`}<div class="actions"><button class="secondary" onclick="this.closest('dialog').close()">Close</button></div>`;document.body.append(d);d.showModal()}
async function requestJoin(id,b){let msg=prompt("Optional message to employer:")||null;let r=await db.from("job_join_requests").insert({job_id:id,worker_id:S.user.id,message:msg});if(r.error)return toast(r.error.message,true);b.disabled=true;b.textContent="Request Sent"}
async function joinCode(){let c=document.getElementById("code").value.trim().toUpperCase();if(!c)return toast("Enter a code.",true);let r=await db.rpc("join_private_job",{p_join_code:c});if(r.error)return toast(r.error.message,true);await load();S.job=S.jobs.find(x=>x.id===r.data);render();toast("Joined job.")}
async function createTask(){let t=document.getElementById("tt").value.trim(),w=document.getElementById("tw").value,p=+document.getElementById("tp").value||0;if(!t||!w)return toast("Enter a title and choose a worker.",true);let r=await db.from("tasks").insert({job_id:S.job.id,assigned_worker_id:w,created_by:S.user.id,title:t,description:document.getElementById("td").value.trim()||null,pay_amount:p});if(r.error)return toast(r.error.message,true);render();toast("Task assigned.")}
async function completeTask(id){let r=await db.from("tasks").update({status:"completed",completed_at:new Date().toISOString()}).eq("id",id).eq("assigned_worker_id",S.user.id);if(r.error)return toast(r.error.message,true);render();toast("Marked complete.")}
async function approveTask(id){let r=await db.from("tasks").update({status:"approved",approved_at:new Date().toISOString(),approved_by:S.user.id}).eq("id",id).eq("job_id",S.job.id);if(r.error)return toast(r.error.message,true);render();toast("Task approved.")}
async function saveJob(){let r=await db.from("jobs").update({name:document.getElementById("en").value.trim(),description:document.getElementById("ed").value.trim()||null,visibility:document.getElementById("ev").value}).eq("id",S.job.id).select().single();if(r.error)return toast(r.error.message,true);S.job=r.data;S.jobs=S.jobs.map(j=>j.id===r.data.id?r.data:j);render();toast("Saved.")}
const originalRender=render;
render=async function(){
  theme();
  if(!S.user||!S.profile){
    app.innerHTML=S.need2fa?codeScreen():S.user?setup():auth();
    return;
  }
  app.innerHTML=wrap(S.profile.role==="manager"?manager():worker());
  if(S.job){
    if(S.profile.role==="manager"&&S.tab==="home")await loadManagerHome();
    if(S.profile.role==="manager"&&S.tab==="workers")await loadWorkers();
    if(S.profile.role==="manager"&&S.tab==="requests"){await loadRequests();await loadTimeOff()}
    if(S.profile.role==="manager"&&S.tab==="tasks")await loadTasks();
    if(S.profile.role==="worker"&&S.tab==="home"){await loadWorkerHome();await loadWSchedule()}
    if(S.profile.role==="manager"&&S.tab==="schedule"){await loadSchedule();await loadMCal()}
    if(S.profile.role==="manager"&&S.tab==="payroll")await loadPayroll();
    if(S.profile.role==="manager"&&S.tab==="time")await loadTime();
    if(S.profile.role==="worker"&&S.tab==="schedule"){await loadWSchedule();await loadWReq()}
    if(S.profile.role==="worker"&&S.tab==="pay")await loadWPay();
    if(S.profile.role==="worker"&&S.tab==="history"){let b=document.getElementById("wbox");if(b)b.innerHTML=await whistoryData()}
    if(S.profile.role==="worker"&&S.tab==="tasks"){let b=document.getElementById("wbox");if(b)b.innerHTML=await wtasksData()}
  }
}

async function needMfa(){try{let a=await db.auth.mfa.getAuthenticatorAssuranceLevel();return !!(a.data&&a.data.nextLevel==="aal2"&&a.data.currentLevel!=="aal2")}catch(e){return false}}
function codeScreen(){return `<div class="auth"><div class="hero"><div class="logo">🔐</div><h1>Enter Code</h1><p>Open your authenticator app and enter the 6-digit code for TimeClock.</p></div>
<div class="card">${banner()}<label>6-digit code</label><input id="mcode" type="text" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="123456">
<div class="actions"><button class="primary" onclick="verifyLogin()">Verify</button><button class="secondary" onclick="logout()">Cancel</button></div></div></div>`}
async function verifyLogin(){let code=(document.getElementById("mcode").value||"").trim();if(code.length!==6)return toast("Enter the 6-digit code.",true);let l=await db.auth.mfa.listFactors();let f=((l.data&&l.data.totp)||[]).find(x=>x.status==="verified");if(!f)return toast("No 2FA found. Sign out and try again.",true);let c=await db.auth.mfa.challenge({factorId:f.id});if(c.error)return toast(friendly(c.error.message),true);let v=await db.auth.mfa.verify({factorId:f.id,challengeId:c.data.id,code});if(v.error)return toast("Wrong code. Try again.",true);await load();render()}
async function mfaDialog(){
 let l=await db.auth.mfa.listFactors();if(l.error)return toast(friendly(l.error.message),true);
 let f=((l.data&&l.data.totp)||[]).find(x=>x.status==="verified");
 let d=document.createElement("dialog");
 d.innerHTML=f?`<h2>🔐 2FA is ON</h2><p>Your account asks for an authenticator code every time you sign in.</p><div class="actions"><button class="danger" id="mfaoff">Turn Off 2FA</button><button class="secondary" id="mfax">Close</button></div>`
 :`<h2>🔐 Set Up 2FA</h2><p>Adds a 6-digit code from an authenticator app (Google Authenticator, Microsoft Authenticator, or Authy) every time you sign in.</p><div id="mfabody"><div class="actions"><button class="primary" id="mfaon">Start Setup</button><button class="secondary" id="mfax">Close</button></div></div>`;
 document.body.append(d);d.showModal();
 const close=()=>{d.close();d.remove()};
 d.querySelector("#mfax").onclick=close;
 if(f){d.querySelector("#mfaoff").onclick=async()=>{let r=await db.auth.mfa.unenroll({factorId:f.id});close();if(r.error)return toast(friendly(r.error.message),true);toast("2FA turned off.")};return}
 d.querySelector("#mfaon").onclick=async()=>{
  for(let x of ((l.data&&l.data.all)||[]).filter(x=>x.status==="unverified")){await db.auth.mfa.unenroll({factorId:x.id})}
  let e=await db.auth.mfa.enroll({factorType:"totp",friendlyName:"TimeClock "+Date.now()});
  if(e.error){close();return toast(friendly(e.error.message),true)}
  d.querySelector("#mfabody").innerHTML=`<p>1. Scan this code with your authenticator app.</p><div style="text-align:center;background:#fff;padding:8px;border-radius:10px"><img src="${e.data.totp.qr_code}" alt="QR code" style="width:200px;height:200px"></div><p class="small">Can't scan? Type this key into the app: <b style="word-break:break-all;user-select:all">${esc(e.data.totp.secret)}</b></p><p>2. Enter the 6-digit code it shows.</p><input id="mfac" type="text" inputmode="numeric" maxlength="6" placeholder="123456"><div class="actions"><button class="primary" id="mfav">Turn On 2FA</button><button class="secondary" id="mfax2">Cancel</button></div>`;
  d.querySelector("#mfax2").onclick=async()=>{await db.auth.mfa.unenroll({factorId:e.data.id});close()};
  d.querySelector("#mfav").onclick=async()=>{let code=d.querySelector("#mfac").value.trim();if(code.length!==6)return alert("Enter the 6-digit code.");let c=await db.auth.mfa.challenge({factorId:e.data.id});if(c.error)return alert(friendly(c.error.message));let v=await db.auth.mfa.verify({factorId:e.data.id,challengeId:c.data.id,code});if(v.error)return alert("Wrong code. Check your app and try again.");close();toast("2FA is on. You'll need a code next time you sign in.")}
 }
}
function secCard(){return `<div class="card"><h2>🔐 Two-Factor Authentication</h2><p>Protect your account with a 6-digit code from an authenticator app.</p><div class="actions"><button class="primary" onclick="mfaDialog()">Manage 2FA</button></div></div>`}
const _ms=msettings,_ws=wsettings;
msettings=function(){return _ms()+secCard()};
wsettings=function(){return _ws()+secCard()};

/* ===== Schedules + Payroll ===== */
const ymd=d=>new Date(d-d.getTimezoneOffset()*6e4).toISOString().slice(0,10);
function whistory(){return `<div id="wbox" class="card">Loading...</div>`}
function wtasks(){return `<div id="wbox" class="card">Loading...</div>`}
async function actWorkers(){let m=await db.from("job_workers").select("id,worker_id,status,hourly_rate").eq("job_id",S.job.id);let all=m.data||[];let ids=all.map(x=>x.worker_id);let p=ids.length?await db.from("profiles").select("id,name").in("id",ids):{data:[]};return{rows:all.filter(x=>x.status==="active"),names:new Map((p.data||[]).map(x=>[x.id,x.name]))}}
const back=`<button class="secondary" onclick="S.job=null;render()">← Jobs</button>`;
function mschedule(){return `<div class="row"><div><h1>🗓️ Schedule</h1><p>Assign shifts to your workers.</p></div>${back}</div><div class="card"><h2>New Shift</h2><label>Worker</label><select id="sw"><option value="">Choose worker</option></select><label>Date</label><input id="sd" type="date" value="${ymd(new Date())}"><label>Start</label><input id="ss" type="time" value="09:00"><label>End</label><input id="se" type="time" value="17:00"><label>Notes</label><input id="sn" placeholder="Optional"><div class="actions"><button class="primary" onclick="addShift()">Add Shift</button></div></div><div class="card"><h2>Upcoming Shifts</h2><div id="sl">Loading...</div></div>`}
async function loadSchedule(){let {rows,names}=await actWorkers();let sel=document.getElementById("sw");if(sel)sel.innerHTML=`<option value="">Choose worker</option>`+rows.map(x=>`<option value="${x.worker_id}">${esc(names.get(x.worker_id)||"Worker")}</option>`).join("");let r=await db.from("shifts").select("*").eq("job_id",S.job.id).gte("end_time",new Date(Date.now()-864e5).toISOString()).order("start_time");document.getElementById("sl").innerHTML=r.error?`<div class="empty">${esc(r.error.message)}</div>`:(r.data||[]).map(x=>`<div class="item row"><div><b>${esc(names.get(x.worker_id)||"Worker")}</b><div class="small">${date(x.start_time)} → ${date(x.end_time)}${x.notes?" · "+esc(x.notes):""}</div></div><button class="danger" onclick="delShift('${x.id}')">Delete</button></div>`).join("")||`<div class="empty">No shifts yet.</div>`}
async function addShift(){let g=i=>document.getElementById(i).value,w=g("sw"),d=g("sd"),s=g("ss"),e=g("se");if(!w||!d||!s||!e)return toast("Choose a worker, date, start and end.",true);let st=new Date(d+"T"+s),en=new Date(d+"T"+e);if(en<=st)en=new Date(en.getTime()+864e5);let r=await db.from("shifts").insert({job_id:S.job.id,worker_id:w,start_time:st.toISOString(),end_time:en.toISOString(),notes:g("sn").trim()||null});if(r.error)return toast(r.error.message,true);render();toast("Shift added.")}
async function delShift(id){if(!confirm("Delete this shift?"))return;let r=await db.from("shifts").delete().eq("id",id);if(r.error)return toast(r.error.message,true);render()}
function mpayroll(){let t=new Date();return `<div class="row"><div><h1>💵 Payroll</h1><p>Set pay rates, then generate paychecks from hours and approved tasks.</p></div>${back}</div><div class="card"><h2>Hourly Rates</h2><div id="pr">Loading...</div></div><div class="card"><h2>Generate Paychecks</h2><label>Period start</label><input id="ps" type="date" value="${ymd(new Date(t-6*864e5))}"><label>Period end</label><input id="pe" type="date" value="${ymd(t)}"><div class="actions"><button class="primary" onclick="genPay()">Generate</button></div></div><div class="card"><h2>Paychecks</h2><div id="pl">Loading...</div></div>`}
async function loadPayroll(){let {rows,names}=await actWorkers();document.getElementById("pr").innerHTML=rows.map(x=>`<div class="item row"><b>${esc(names.get(x.worker_id)||"Worker")}</b><div class="row"><input id="rate_${x.id}" type="number" min="0" step=".01" value="${x.hourly_rate||0}" style="width:100px"><button class="secondary" onclick="saveRate('${x.id}')">Save</button></div></div>`).join("")||`<div class="empty">No workers yet.</div>`;let r=await db.from("paychecks").select("*").eq("job_id",S.job.id).order("created_at",{ascending:false});document.getElementById("pl").innerHTML=r.error?`<div class="empty">${esc(r.error.message)}</div>`:(r.data||[]).map(x=>`<div class="item"><div class="row"><b>${esc(names.get(x.worker_id)||"Worker")}</b><span class="badge">${x.status}</span></div><p>${x.period_start} → ${x.period_end}<br>${hrsTxt(x)} × ${money(x.hourly_rate)} + tasks ${money(x.task_pay)}<br><b>Total ${money(x.total)}</b></p><div class="actions">${x.status==="pending"?`<button class="success" onclick="markPaid('${x.id}')">Mark Paid</button><button class="danger" onclick="delPay('${x.id}')">Delete</button>`:`<span class="small">Paid ${date(x.paid_at)}</span>`}</div></div>`).join("")||`<div class="empty">No paychecks yet.</div>`}
async function saveRate(id){let v=+document.getElementById("rate_"+id).value||0;let r=await db.from("job_workers").update({hourly_rate:v}).eq("id",id);if(r.error)return toast(r.error.message,true);toast("Rate saved.")}
async function markPaid(id){let r=await db.from("paychecks").update({status:"paid",paid_at:new Date().toISOString()}).eq("id",id);if(r.error)return toast(r.error.message,true);render();toast("Marked paid.")}
async function delPay(id){if(!confirm("Delete this paycheck?"))return;let r=await db.from("paychecks").delete().eq("id",id);if(r.error)return toast(r.error.message,true);render()}
function wpay(){return `<div class="row"><h1>💵 My Pay</h1><button class="secondary" onclick="S.job=null;load();render()">← My Jobs</button></div><div class="card" id="wpl">Loading...</div>`}
async function loadWPay(){let r=await db.from("paychecks").select("*").eq("job_id",S.job.id).eq("worker_id",S.user.id).order("created_at",{ascending:false});document.getElementById("wpl").innerHTML=r.error?`<div class="empty">${esc(r.error.message)}</div>`:(r.data||[]).map(x=>`<div class="item"><div class="row"><b>${x.period_start} → ${x.period_end}</b><span class="badge">${x.status}</span></div><p>${hrsTxt(x)} × ${money(x.hourly_rate)} + tasks ${money(x.task_pay)}<br><b>Total ${money(x.total)}</b></p></div>`).join("")||`<div class="empty">No paychecks yet.</div>`}

/* ===== Worker schedule: week/day view with hours ===== */
const hm=h=>{let m=Math.round(h*60);return Math.floor(m/60)+"h "+(m%60)+"m"};
const tm=x=>new Date(x).toLocaleTimeString([],{hour:"numeric",minute:"2-digit"});
function wRange(){let a=new Date(+(S.sd||Date.now()));a.setHours(0,0,0,0);let wk=(S.sv||"week")==="week";if(wk)a.setDate(a.getDate()-(a.getDay()+6)%7);let b=new Date(a);b.setDate(b.getDate()+(wk?7:1));return{a,b,wk}}
function wToday(){S.sd=Date.now();render()}
function wView(v){S.sv=v;render()}
const _wh=whome;whome=function(){return _wh()+wschedBlock()};
async function loadWSchedule(){if((S.sv||"week")==="month")return loadWMonth();let {a,b,wk}=wRange(),q=t=>db.from(t).select("*").eq("job_id",S.job.id).eq("worker_id",S.user.id);
let sh=await q("shifts").gte("start_time",a.toISOString()).lt("start_time",b.toISOString()).order("start_time");
let tr=await q("time_records").gte("clock_in",a.toISOString()).lt("clock_in",b.toISOString()).order("clock_in");
if(sh.error||tr.error){document.getElementById("wsl").innerHTML=`<div class="card empty">${esc((sh.error||tr.error).message)}</div>`;return}
let now=Date.now(),sched=0,done=0,html="";
for(let d=new Date(a);d<b;d.setDate(d.getDate()+1)){let e=new Date(d);e.setDate(e.getDate()+1);
 let ds=(sh.data||[]).filter(x=>new Date(x.start_time)>=d&&new Date(x.start_time)<e);
 let rs=(tr.data||[]).filter(x=>new Date(x.clock_in)>=d&&new Date(x.clock_in)<e);
 let req=ds.reduce((t,x)=>t+(new Date(x.end_time)-new Date(x.start_time))/36e5,0);
 let wh=rs.reduce((t,x)=>t+((x.clock_out?new Date(x.clock_out):now)-new Date(x.clock_in))/36e5,0);
 sched+=req;done+=wh;
 html+=`<div class="card"><div class="row"><b>${d.toLocaleDateString([],{weekday:"long",month:"short",day:"numeric"})}</b>${d.toDateString()===new Date().toDateString()?`<span class="badge">Today</span>`:""}</div>${ds.map(x=>`<p>🗓️ ${tm(x.start_time)} – ${tm(x.end_time)} · <b>${hm((new Date(x.end_time)-new Date(x.start_time))/36e5)} required</b>${x.notes?" · "+esc(x.notes):""}</p>`).join("")||`<p>No shift scheduled.</p>`}<p>⏱️ Worked: <b>${hm(wh)}</b>${req?" of "+hm(req):""}</p>${wk?"":rs.map(x=>`<div class="small">${tm(x.clock_in)} → ${x.clock_out?tm(x.clock_out):"still working"}</div>`).join("")}</div>`}
let last=new Date(b.getFullYear(),b.getMonth(),b.getDate()-1),f=x=>x.toLocaleDateString([],{month:"short",day:"numeric"});
document.getElementById("wrange").textContent=wk?f(a)+" – "+f(last):a.toLocaleDateString([],{weekday:"short",month:"short",day:"numeric"});
document.getElementById("wsum").innerHTML=`Total worked: <b>${hm(done)}</b> · Scheduled: <b>${hm(sched)}</b>`;
document.getElementById("wsl").innerHTML=html}

/* ===== Calendar, days off, breaks ===== */
const ts=x=>{let d=new Date(x),m=d.getMinutes();return (d.getHours()%12||12)+(m?":"+String(m).padStart(2,"0"):"")+(d.getHours()>=12?"p":"a")};
const sameDay=(t,d)=>new Date(t).toDateString()===d.toDateString();
const inDay=(x,d)=>{let e=new Date(d);e.setDate(e.getDate()+1);return new Date(x.start_time)<e&&new Date(x.end_time)>d};
function gridRange(f){let a=new Date(f);a.setDate(a.getDate()-(a.getDay()+6)%7);let b=new Date(f.getFullYear(),f.getMonth()+1,1);while((b.getDay()+6)%7)b.setDate(b.getDate()+1);return{a,b}}
function calGrid(f,cell){let {a,b}=gridRange(f),t=new Date().toDateString();let h=`<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px;font-size:11px">`+["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(x=>`<div class="small" style="text-align:center">${x}</div>`).join("");for(let d=new Date(a);d<b;d.setDate(d.getDate()+1)){let now=d.toDateString()===t;h+=`<div style="min-height:62px;padding:3px;border-radius:8px;overflow:hidden;line-height:1.25;border:${now?"2px solid var(--primary)":"1px solid var(--line)"};${now?"background:rgba(59,109,240,.18);":""}${d.getMonth()!==f.getMonth()?"opacity:.4;":""}"><b>${d.getDate()}</b>${cell(new Date(d))}</div>`}return h+"</div>"}
function wView(v){S.sv=v;render()}
function wShift(n){let d=new Date(+(S.sd||Date.now())),v=S.sv||"week";if(v==="month"){d.setDate(1);d.setMonth(d.getMonth()+n)}else d.setDate(d.getDate()+n*(v==="week"?7:1));S.sd=+d;render()}
function wschedBlock(){let v=S.sv||"week",c=x=>`class="${v===x?"primary":"secondary"}"`;return `<div class="card"><div class="row"><b id="wrange"></b><div class="actions" style="margin:0"><button ${c("week")} onclick="wView('week')">Week</button><button ${c("day")} onclick="wView('day')">Day</button><button ${c("month")} onclick="wView('month')">Month</button></div></div><div class="actions"><button class="secondary" onclick="wShift(-1)">‹ Prev</button><button class="secondary" onclick="wToday()">Today</button><button class="secondary" onclick="wShift(1)">Next ›</button></div><div id="wsum" class="small" style="margin-top:10px"></div></div><div id="wsl">Loading...</div>`}
function wschedule(){return `<div class="row"><h1>🗓️ My Schedule</h1><button class="secondary" onclick="S.job=null;load();render()">← My Jobs</button></div>`+wschedBlock()+reqCard()}
async function loadWMonth(){let d=new Date(+(S.sd||Date.now()));d.setDate(1);d.setHours(0,0,0,0);let g=gridRange(d),A=g.a.toISOString(),B=g.b.toISOString(),q=t=>db.from(t).select("*").eq("job_id",S.job.id).eq("worker_id",S.user.id);let [sh,to]=await Promise.all([q("shifts").gte("start_time",A).lt("start_time",B),q("time_off").neq("status","denied").lt("start_time",B).gt("end_time",A)]);if(sh.error||to.error){document.getElementById("wsl").innerHTML=`<div class="card empty">${esc((sh.error||to.error).message)}</div>`;return}
document.getElementById("wrange").textContent=d.toLocaleDateString([],{month:"long",year:"numeric"});document.getElementById("wsum").innerHTML=`Today is <b>${new Date().toLocaleDateString([],{weekday:"long",month:"long",day:"numeric"})}</b>`;
document.getElementById("wsl").innerHTML=`<div class="card">`+calGrid(d,day=>(sh.data||[]).filter(x=>sameDay(x.start_time,day)).map(x=>`<div>${ts(x.start_time)}–${ts(x.end_time)}</div>`).join("")+(to.data||[]).filter(x=>inDay(x,day)).map(x=>x.kind==="break"?`<div>☕ ${ts(x.start_time)}${x.status==="pending"?"?":""}</div>`:`<div>🏖️ OFF${x.status==="pending"?"?":""}</div>`).join(""))+`<p class="small">? = waiting for approval</p></div>`}
function reqCard(){return `<div class="card"><h2>Request Time Off or a Break</h2><label>Type</label><select id="tk" onchange="tkToggle()"><option value="day_off">🏖️ Day(s) off</option><option value="break">☕ Break</option></select><label id="tl1">From date</label><input id="td1" type="date" value="${ymd(new Date())}"><div id="tdto"><label>To date</label><input id="td2" type="date" value="${ymd(new Date())}"></div><div id="ttm" style="display:none"><label>Start time</label><input id="tt1" type="time" value="12:00"><label>End time</label><input id="tt2" type="time" value="12:30"></div><label>Reason</label><input id="tr" placeholder="Optional"><div class="actions"><button class="primary" onclick="sendTO()">Send Request</button></div></div><div class="card"><h2>My Requests</h2><div id="wreq">Loading...</div></div>`}
function tkToggle(){let b=document.getElementById("tk").value==="break";document.getElementById("tdto").style.display=b?"none":"";document.getElementById("ttm").style.display=b?"":"none";document.getElementById("tl1").textContent=b?"Date":"From date"}
async function sendTO(){let g=i=>document.getElementById(i).value,k=g("tk"),d1=g("td1"),st,en;if(!d1)return toast("Pick a date.",true);if(k==="break"){if(!g("tt1")||!g("tt2"))return toast("Pick start and end times.",true);st=new Date(d1+"T"+g("tt1"));en=new Date(d1+"T"+g("tt2"));if(en<=st)return toast("End time must be after start.",true)}else{let d2=g("td2")||d1;if(d2<d1)return toast("The 'To' date can't be before the 'From' date.",true);st=new Date(d1+"T00:00");en=new Date(d2+"T00:00");en.setDate(en.getDate()+1)}let r=await db.from("time_off").insert({job_id:S.job.id,worker_id:S.user.id,kind:k,start_time:st.toISOString(),end_time:en.toISOString(),reason:g("tr").trim()||null});if(r.error)return toast(r.error.message,true);render();toast("Request sent to your employer.")}
function toLabel(x){if(x.kind==="break")return `☕ Break · ${date(x.start_time)} – ${ts(x.end_time)}`;let e=new Date(x.end_time);e.setDate(e.getDate()-1);let f=y=>new Date(y).toLocaleDateString([],{month:"short",day:"numeric"});return `🏖️ Day off · ${f(x.start_time)}`+(e.toDateString()!==new Date(x.start_time).toDateString()?" – "+f(e):"")}
async function loadWReq(){let r=await db.from("time_off").select("*").eq("job_id",S.job.id).eq("worker_id",S.user.id).order("created_at",{ascending:false}).limit(20);document.getElementById("wreq").innerHTML=r.error?`<div class="empty">${esc(r.error.message)}</div>`:(r.data||[]).map(x=>`<div class="item"><div class="row"><b>${toLabel(x)}</b><span class="badge">${x.status}</span></div>${x.reason?`<p>${esc(x.reason)}</p>`:""}${x.status==="pending"?`<button class="danger" onclick="cancelTO('${x.id}')">Cancel</button>`:""}</div>`).join("")||`<div class="empty">No requests yet.</div>`}
async function cancelTO(id){let r=await db.from("time_off").delete().eq("id",id);if(r.error)return toast(r.error.message,true);render()}
const _mr=mrequests;mrequests=function(){return _mr()+`<div class="card"><h2>Time Off & Breaks</h2><div id="tos">Loading...</div></div>`};
async function loadTimeOff(){let {names}=await actWorkers();let r=await db.from("time_off").select("*").eq("job_id",S.job.id).order("created_at",{ascending:false}).limit(30);document.getElementById("tos").innerHTML=r.error?`<div class="empty">${esc(r.error.message)}</div>`:(r.data||[]).map(x=>`<div class="item"><div class="row"><b>${esc(names.get(x.worker_id)||"Worker")}</b><span class="badge">${x.status}</span></div><p>${toLabel(x)}${x.reason?"<br>"+esc(x.reason):""}</p>${x.status==="pending"?`<div class="actions"><button class="success" onclick="reviewTO('${x.id}','approved')">Approve</button><button class="danger" onclick="reviewTO('${x.id}','denied')">Deny</button></div>`:""}</div>`).join("")||`<div class="empty">No requests.</div>`}
async function reviewTO(id,status){let r=await db.from("time_off").update({status,reviewed_by:S.user.id,reviewed_at:new Date().toISOString()}).eq("id",id);if(r.error)return toast(r.error.message,true);render();toast(status==="approved"?"Approved.":"Denied.")}
const _msch=mschedule;mschedule=function(){return _msch()+`<div class="card"><div class="row"><b id="mcr"></b><div class="actions" style="margin:0"><button class="secondary" onclick="mMonth(-1)">‹</button><button class="secondary" onclick="mMonth(0)">Today</button><button class="secondary" onclick="mMonth(1)">›</button></div></div><div id="mcal">Loading...</div></div>`};
function mMonth(n){if(!n)S.mm=Date.now();else{let d=new Date(+(S.mm||Date.now()));d.setDate(1);d.setMonth(d.getMonth()+n);S.mm=+d}render()}
async function loadMCal(){let d=new Date(+(S.mm||Date.now()));d.setDate(1);d.setHours(0,0,0,0);let g=gridRange(d),A=g.a.toISOString(),B=g.b.toISOString(),{names}=await actWorkers(),fn=id=>esc((names.get(id)||"Worker").split(" ")[0]);let [sh,to]=await Promise.all([db.from("shifts").select("*").eq("job_id",S.job.id).gte("start_time",A).lt("start_time",B),db.from("time_off").select("*").eq("job_id",S.job.id).eq("kind","day_off").neq("status","denied").lt("start_time",B).gt("end_time",A)]);let el=document.getElementById("mcal");if(!el)return;if(sh.error||to.error){el.innerHTML=`<div class="empty">${esc((sh.error||to.error).message)}</div>`;return}
document.getElementById("mcr").textContent=d.toLocaleDateString([],{month:"long",year:"numeric"});
el.innerHTML=calGrid(d,day=>{let l=(sh.data||[]).filter(x=>sameDay(x.start_time,day)).map(x=>`<div>${fn(x.worker_id)} ${ts(x.start_time)}</div>`);let o=(to.data||[]).filter(x=>inDay(x,day)).map(x=>`<div>🏖️ ${fn(x.worker_id)}${x.status==="pending"?"?":""}</div>`);return l.slice(0,3).join("")+(l.length>3?`<div>+${l.length-3} more</div>`:"")+o.join("")})+`<p class="small">🏖️ = day off · ? = waiting for approval</p>`}
const _as=addShift;addShift=async function(){let w=document.getElementById("sw").value,d=document.getElementById("sd").value;if(w&&d){let a=new Date(d+"T00:00"),b=new Date(a);b.setDate(b.getDate()+1);let t=await db.from("time_off").select("id").eq("job_id",S.job.id).eq("worker_id",w).eq("status","approved").eq("kind","day_off").lt("start_time",b.toISOString()).gt("end_time",a.toISOString()).limit(1);if(t.data&&t.data.length&&!confirm("This worker has approved time off that day. Add the shift anyway?"))return}return _as()};
let lastDay=new Date().toDateString();document.addEventListener("visibilitychange",()=>{if(!document.hidden&&lastDay!==new Date().toDateString()){lastDay=new Date().toDateString();if(S.user&&S.profile)render()}});

/* ===== Manager time edits, overtime, CSV export ===== */
const ge=i=>document.getElementById(i).value;
const hrsTxt=x=>`${Number(x.hours).toFixed(2)}h`+(Number(x.overtime_hours)?` (${Number(x.overtime_hours).toFixed(2)}h OT)`:"");
const tli=x=>new Date(new Date(x)-new Date(x).getTimezoneOffset()*6e4).toISOString().slice(0,16);
function mtime(){return `<div class="row"><div><h1>⏱️ Time Records</h1><p>Fix or add hours for your workers.</p></div>${back}</div><div class="card"><h2>Add Time Record</h2><label>Worker</label><select id="rw"><option value="">Choose worker</option></select><label>Clock in</label><input id="ri" type="datetime-local"><label>Clock out</label><input id="ro" type="datetime-local"><div class="actions"><button class="primary" onclick="addRec()">Add Record</button></div></div><div class="card"><h2>Last 14 Days</h2><div id="rl">Loading...</div></div>`}
async function loadTime(){let {rows,names}=await actWorkers();let sel=document.getElementById("rw");if(sel)sel.innerHTML=`<option value="">Choose worker</option>`+rows.map(x=>`<option value="${x.worker_id}">${esc(names.get(x.worker_id)||"Worker")}</option>`).join("");let r=await db.from("time_records").select("*").eq("job_id",S.job.id).gte("clock_in",new Date(Date.now()-14*864e5).toISOString()).order("clock_in",{ascending:false});document.getElementById("rl").innerHTML=r.error?`<div class="empty">${esc(r.error.message)}</div>`:(r.data||[]).map(x=>`<div class="item row"><div><b>${esc(names.get(x.worker_id)||"Worker")}</b><div class="small">${date(x.clock_in)} → ${x.clock_out?date(x.clock_out)+" · "+dur(x.clock_in,x.clock_out):"still working"}${x.manager_edited?" · edited":""}</div></div><div class="actions" style="margin:0"><button class="secondary" onclick="editRec('${x.id}','${x.clock_in}','${x.clock_out||""}')">Edit</button><button class="danger" onclick="delRec('${x.id}')">Delete</button></div></div>`).join("")||`<div class="empty">No records.</div>`}
function editRec(id,a,b){let d=document.createElement("dialog");d.innerHTML=`<h2>Edit Time Record</h2><label>Clock in</label><input id="ei" type="datetime-local" value="${tli(a)}"><label>Clock out (empty = still working)</label><input id="eo" type="datetime-local" value="${b?tli(b):""}"><div class="actions"><button class="primary" id="es">Save</button><button class="secondary" id="ec">Cancel</button></div>`;document.body.append(d);d.showModal();d.querySelector("#ec").onclick=()=>{d.close();d.remove()};d.querySelector("#es").onclick=async()=>{let i=d.querySelector("#ei").value,o=d.querySelector("#eo").value;if(!i)return alert("Enter a clock in time.");if(o&&new Date(o)<=new Date(i))return alert("Clock out must be after clock in.");let r=await db.from("time_records").update({clock_in:new Date(i).toISOString(),clock_out:o?new Date(o).toISOString():null,manager_edited:true,edited_by:S.user.id,edited_at:new Date().toISOString()}).eq("id",id).select();d.close();d.remove();if(r.error)return toast(r.error.message,true);if(!r.data.length)return toast("Couldn't save: the database blocked it.",true);render();toast("Record updated.")}}
async function addRec(){let w=ge("rw"),i=ge("ri"),o=ge("ro");if(!w||!i)return toast("Choose a worker and a clock in time.",true);if(o&&new Date(o)<=new Date(i))return toast("Clock out must be after clock in.",true);let r=await db.from("time_records").insert({job_id:S.job.id,worker_id:w,clock_in:new Date(i).toISOString(),clock_out:o?new Date(o).toISOString():null,manager_edited:true,edited_by:S.user.id,edited_at:new Date().toISOString()});if(r.error)return toast(r.error.message,true);render();toast("Record added.")}
async function delRec(id){if(!confirm("Delete this time record?"))return;let r=await db.from("time_records").delete().eq("id",id).select();if(r.error)return toast(r.error.message,true);if(!r.data.length)return toast("Couldn't delete: run the security SQL first.",true);render()}
const _mp=mpayroll;mpayroll=function(){return _mp().replace('<div class="actions"><button class="primary" onclick="genPay()">','<label>Overtime after (hours per week, 0 = off)</label><input id="otl" type="number" value="40"><label>Overtime pay multiplier</label><input id="otm" type="number" step=".1" value="1.5"><div class="actions"><button class="primary" onclick="genPay()">').replace('<h2>Paychecks</h2>','<h2>Paychecks</h2><button class="secondary" onclick="exportPay()">⬇️ Export CSV</button>')};
async function genPay(){let s=ge("ps"),e=ge("pe");if(!s||!e||e<s)return toast("Pick a valid period.",true);let otl=+ge("otl")||0,otm=+ge("otm")||1.5,days=Math.round((new Date(e)-new Date(s))/864e5)+1,from=new Date(s+"T00:00").toISOString(),to=new Date(new Date(e+"T00:00").getTime()+864e5).toISOString();let {rows}=await actWorkers(),made=0;for(let w of rows){let ex=await db.from("paychecks").select("id").eq("job_id",S.job.id).eq("worker_id",w.worker_id).eq("period_start",s).eq("period_end",e).limit(1);if(ex.data&&ex.data.length)continue;let t=await db.from("time_records").select("clock_in,clock_out").eq("job_id",S.job.id).eq("worker_id",w.worker_id).gte("clock_in",from).lt("clock_in",to).not("clock_out","is",null);let h=Math.round((t.data||[]).reduce((a,x)=>a+(new Date(x.clock_out)-new Date(x.clock_in))/36e5,0)*100)/100;let k=await db.from("tasks").select("pay_amount").eq("job_id",S.job.id).eq("assigned_worker_id",w.worker_id).eq("status","approved").gte("approved_at",from).lt("approved_at",to);let tp=(k.data||[]).reduce((a,x)=>a+Number(x.pay_amount||0),0);if(!h&&!tp)continue;let rate=Number(w.hourly_rate||0),ot=otl>0?Math.round(Math.max(0,h-otl*days/7)*100)/100:0;let r=await db.from("paychecks").insert({job_id:S.job.id,worker_id:w.worker_id,period_start:s,period_end:e,hours:h,overtime_hours:ot,hourly_rate:rate,task_pay:tp,total:Math.round(((h-ot)*rate+ot*rate*otm+tp)*100)/100});if(r.error)return toast(r.error.message,true);made++}render();toast(made?made+" paycheck(s) created.":"Nothing to pay for that period.")}
async function exportPay(){let {names}=await actWorkers();let r=await db.from("paychecks").select("*").eq("job_id",S.job.id).order("period_start",{ascending:false});if(r.error)return toast(r.error.message,true);let q=v=>`"${String(v??"").replace(/"/g,'""')}"`,rows=[["Worker","Period start","Period end","Hours","Overtime hours","Hourly rate","Task pay","Total","Status","Paid at"]].concat((r.data||[]).map(x=>[names.get(x.worker_id)||"Worker",x.period_start,x.period_end,x.hours,x.overtime_hours||0,x.hourly_rate,x.task_pay,x.total,x.status,x.paid_at||""])),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([rows.map(l=>l.map(q).join(",")).join("\n")],{type:"text/csv"}));a.download="paychecks.csv";document.body.append(a);a.click();a.remove()}
